solution:
fn to_grade(score: Int) -> Result[Str, Str] {
  if score < 0 || score > 100 {
    return Err("Score must be between 0 and 100");
  }
  if score >= 90 {
    return Ok("A");
  } elif score >= 80 {
    return Ok("B");
  } elif score >= 70 {
    return Ok("C");
  } elif score >= 60 {
    return Ok("D");
  } else {
    return Ok("F");
  }
}

fn main() -> Int {
  match to_grade(85) {
    Ok("B") => { return 300; }
    Ok(_) => { return 400; }
    Err(_) => { return 500; }
  }
}
